from html.parser import HTMLParser
from pathlib import Path
import subprocess, re
html=Path('index.html').read_text()
class Check(HTMLParser):
 def __init__(self):
  super().__init__(); self.stack=[]; self.ids=[]; self.refs=[]; self.assets=[]
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if 'id' in a: self.ids.append(a['id'])
  for key in ('for','aria-labelledby','aria-describedby'):
   self.refs.extend(a.get(key,'').split())
  if a.get('href','').startswith('#') and a['href']"'!='"'#': self.refs.append(a['href'][1:])
  if 'src' in a or (tag=='link' and 'href' in a): self.assets.append(a)
  if tag not in ('meta','input','br','hr','link','img','area','base','col','embed','param','source','track','wbr'): self.stack.append(tag)
 def handle_endtag(self,tag):
  assert self.stack and self.stack[-1]==tag, (tag,self.stack)
  self.stack.pop()
p=Check();p.feed(html)
assert not p.stack,p.stack
assert len(p.ids)==len(set(p.ids)),'duplicate ids'
assert set(p.refs)<=set(p.ids),set(p.refs)-set(p.ids)
assert not p.assets,p.assets
script=re.search(r'<script>(.*?)</script>',html,re.S).group(1)
r=subprocess.run(['node','--check'],input=script,text=True,capture_output=True)
assert r.returncode==0,r.stderr
print('PASS: HTML nesting, unique IDs, label/ARIA/fragment references, zero external asset references.')
print('PASS: inline JavaScript parses with node --check.')
# Synthetic DOM stub checks JS control flow; not browser or native validation verification.
harness=r'''
const assert = require('node:assert/strict');
const vm = require('node:vm');
const ids = {};
let focused;
function element(id) {
 return ids[id] = {value:'', hidden:false, textContent:'', disabled:true, attrs:{}, handlers:{}, validity:{valid:false},
  setAttribute(k,v){this.attrs[k]=v;}, focus(){focused=id;}, addEventListener(k,fn){this.handlers[k]=fn;}};
}
['estimate-form','email','description','confirmation','error-summary','piece-error','email-error','description-error','summary-piece','summary-email','summary-description','confirmation-title','edit-request','submit-request'].forEach(element);
const radios=['Chair','Table','Cabinet'].map(value => {const r=element(value);r.value=value;r.checked=false;return r;});
ids['estimate-form'].querySelectorAll=()=>radios;
vm.runInNewContext(SOURCE,{document:{getElementById:id=>ids[id]}});
const form=ids['estimate-form'];
function submit(){let prevented=false;form.handlers.submit({preventDefault(){prevented=true;}});assert.ok(prevented);}
assert.equal(ids['submit-request'].disabled,false);
submit();assert.equal(focused,'Chair');assert.equal(ids['piece-error'].hidden,false);
radios[0].checked=true;submit();assert.equal(focused,'email');
ids.email.value='bad';ids.email.validity.valid=false;submit();assert.equal(focused,'email');
ids.email.value=' sam@example.com ';ids.email.validity.valid=true;ids.description.value='   ';submit();assert.equal(focused,'description');
for(let i=0;i<3;i++){
 radios.forEach((r,n)=>r.checked=n===i);
 ids.description.value='  Loose joint <img src=x onerror=alert(1)>  ';
 submit();
 assert.equal(form.hidden,true);assert.equal(ids.confirmation.hidden,false);
 assert.equal(ids['summary-piece'].textContent,radios[i].value);
 assert.equal(ids['summary-email'].textContent,'sam@example.com');
 assert.equal(ids['summary-description'].textContent,'Loose joint <img src=x onerror=alert(1)>');
 assert.equal(focused,'confirmation-title');
 ids['edit-request'].handlers.click();
 assert.equal(form.hidden,false);assert.equal(ids.confirmation.hidden,true);
 assert.equal(focused,radios[i].value);assert.ok(ids.description.value.includes('Loose joint'));
}
ids.description.value='x'.repeat(3001);submit();assert.equal(focused,'description');
ids.description.value='Loose table leg';form.handlers.input();assert.equal(ids['description-error'].hidden,true);
console.log('PASS: synthetic DOM checks for blank/malformed/whitespace/overlength errors, all three furniture choices, confirmation text, safe text assignment, focus calls, edit preservation and error clearing. Email validity is stubbed, not browser-tested.');
'''
import json
r=subprocess.run(['node'],input='const SOURCE='+json.dumps(script)+';\\n'+harness,text=True,capture_output=True)
print(r.stdout,end='');assert r.returncode==0,r.stderr
# WCAG relative-luminance calculation for text token pairs.
def lum(h):
 values=[int(h[i:i+2],16)/255 for i in (0,2,4)]
 values=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in values]
 return sum(v*w for v,w in zip(values,(.2126,.7152,.0722)))
for a,b in [('123347','FAF7F0'),('A9532B','FAF7F0'),('E5CEAA','123347')]:
 x,y=sorted([lum(a),lum(b)]); ratio=(y+.05)/(x+.05)
 assert ratio>=4.5
 print(f'PASS: computed #{a}/#{b} contrast {ratio:.2f}:1.')
PY"

